"  const getFilteredTablesForCurrentView = () => {
    return tables.filter(t => {
      // 1. Order mode filters from activeDepartment
      if (activeDepartment === 'Dining') {
        if (t.is_temporary && t.original_order_type !== 'DINE_IN') return false;
      } else if (activeDepartment === 'Pickup') {
        if (!t.is_temporary || t.original_order_type !== 'PICKUP' || t.original_sub_order_type === 'DELIVERY') return false;
      } else if (activeDepartment === 'Delivery') {
        if (!t.is_temporary || t.original_order_type !== 'PICKUP' || t.original_sub_order_type !== 'DELIVERY') return false;
      } else if (activeDepartment === 'Preorder') {
        if (!t.is_temporary || t.original_order_type !== 'PRE_ORDER') return false;
      } else if (activeDepartment !== 'All') {
        // Database-configured departments (e.g. Ground Floor)
        if (t.department_name !== activeDepartment) return false;
      } else {
        // activeDepartment === 'All' -> fall back to default orderType filter
        if (orderType === 'DINE_IN') {
          if (t.is_temporary && t.original_order_type !== 'DINE_IN') return false;
        } else if (orderType === 'PICKUP') {
          if (t.is_temporary && t.original_order_type !== 'PICKUP') return false;
        } else if (orderType === 'PRE_ORDER') {
          if (t.is_temporary && t.original_order_type !== 'PRE_ORDER') return false;
        } else {
          if (t.is_temporary) return false;
        }
      }

      // 2. Search query filter
      if (tableSearchQuery) {
        if (!t.table_name.toLowerCase().includes(tableSearchQuery.toLowerCase())) return false;
      }
      return true;
    });
  };"

